<script setup>
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {TabsRoot,TabsList,TabsTrigger,TabsContent} from 'reka-ui'
import {api} from '../../useLearning.js'
import {artwork,icon} from '../../assets.js'
import {entryArt,learningExamples,sampleById} from '../../entryContent.js'
const emit=defineEmits(['new-goal','start-course'])
const selected=ref(sampleById(new URLSearchParams(location.search).get('course')).id),activeTab=ref('read'),explanation=ref(false),choice=ref(''),practiceChoice=ref(''),pack=ref(null),loading=ref(false),error=ref(''),demoPrompt=ref('')
const example=computed(()=>sampleById(selected.value)),lesson=computed(()=>pack.value?.lessons.find(l=>l.id===example.value.lesson))
const nextExample=computed(()=>learningExamples[(learningExamples.findIndex(e=>e.id===selected.value)+1)%learningExamples.length])
let revision=0,disposed=false
async function load(){const version=++revision;loading.value=true;error.value='';pack.value=null;try{const result=await api('/catalog/'+selected.value);if(version===revision&&!disposed)pack.value=result}catch(e){if(version===revision&&!disposed)error.value=e.message}finally{if(version===revision&&!disposed)loading.value=false}}
function select(id){selected.value=id;history.replaceState(null,'','/examples?course='+id)}
watch(selected,()=>{activeTab.value='read';explanation.value=false;choice.value='';practiceChoice.value='';demoPrompt.value='';load()})
onMounted(load);onUnmounted(()=>{disposed=true;++revision})
</script>

<template>
<main id="entry-content" class="entry-examples entry-container" tabindex="-1">
  <header class="entry-page-title"><a href="/" class="entry-breadcrumb">首页</a><span class="entry-breadcrumb"> / 学习示例</span><h1>先体验一个问题，看看怎样学。</h1><p>选择示例，了解资料、讨论与练习如何连起来。</p><span class="entry-demo-label">示例内容 · 不写入个人记录</span><img :src="entryArt.arch" alt="" class="entry-page-art"></header>
  <div class="entry-example-layout"><aside class="entry-example-selector"><h2>选择一个学习示例</h2><a v-for="item in learningExamples" :key="item.id" :href="'/examples?course='+item.id" :class="{active:selected===item.id}" :aria-current="selected===item.id?'true':undefined" @click.prevent="select(item.id)"><div><h3>{{ item.tag }}</h3><p>{{ item.title }}</p></div><img :src="item.art" alt=""><img :src="icon('chevron-right')" alt=""></a><button class="entry-text-link" @click="emit('new-goal')"><span aria-hidden="true">⊕</span>也可以从自己的跨学科问题开始</button></aside>
    <TabsRoot v-model="activeTab" class="entry-example-panel"><TabsList aria-label="学习示例内容" class="entry-example-tabs"><TabsTrigger value="read">阅读材料</TabsTrigger><TabsTrigger value="discuss">与林知讨论</TabsTrigger><TabsTrigger value="practice">试着解释</TabsTrigger></TabsList>
      <TabsContent value="read" class="entry-tab-body"><header><h2>{{ example.heading }}</h2><span>自编示例讲义</span></header><h3 class="entry-question-strip">{{ example.question }}</h3><p>{{ example.context }}</p><pre v-if="example.code" class="entry-code"><code>{{ example.code }}</code></pre><div v-if="example.formulas.length" class="entry-example-equations"><div><p v-for="formula in example.formulas" :key="formula">{{ formula }}</p></div><figure v-if="example.id==='mathematics'" class="entry-price-bars" aria-label="情境价格变化：原价80元，上涨后100元，下调后75元"><div v-for="[label,width] in [['80元',80],['100元',100],['75元',75]]" :key="label"><span>{{ label }}</span><i :style="{width:width+'%'}"></i></div><figcaption>价格变化示意</figcaption></figure></div><p class="entry-takeaway">{{ example.takeaway }}</p>
        <div class="entry-sample-question"><img :src="artwork.mentor" alt="林知"><div><h3>林知想问你</h3><p>{{ example.prompt }}</p></div><fieldset><legend class="entry-visually-hidden">{{ example.prompt }}</legend><label v-for="option in example.options" :key="option" :class="{selected:choice===option}"><input v-model="choice" type="radio" :name="'example-'+example.id" :value="option">{{ option }}</label></fieldset><p v-if="choice" class="entry-local-feedback" role="status">{{ choice===example.answer?example.reason:example.hint }}</p></div>
        <div class="entry-example-actions"><button class="entry-text-link" :aria-expanded="explanation" aria-controls="example-reasoning" @click="explanation=!explanation">{{ explanation?'收起讲解思路':'查看讲解思路' }}<img :src="icon('chevron-right')" alt=""></button><button class="entry-button" @click="emit('start-course',example)">用这个示例开始学习<img :src="icon('arrow-right','white')" alt=""></button></div>
        <section v-if="explanation" id="example-reasoning" class="entry-reasoning"><h3>把思路一步步写清楚</h3><ol><li v-for="item in example.explanation" :key="item">{{ item }}</li></ol><p>接下来换一道题，检查你是否能独立解释。</p><button class="entry-text-link" @click="activeTab='practice'">试一道新的示例练习</button></section>
        <details class="entry-source-detail"><summary>查看这份示例的课程来源</summary><p v-if="loading" role="status">正在读取自编课程…</p><div v-else-if="error" role="alert"><p>{{ error }}</p><button class="entry-button secondary" @click="load">重新读取课程</button></div><template v-else-if="lesson"><h3>{{ lesson.title }}</h3><div v-for="section in lesson.sections" :key="section.title"><h4>{{ section.title }}</h4><p>{{ section.text }}</p></div></template></details>
      </TabsContent>
      <TabsContent value="discuss" class="entry-tab-body"><header><h2>围绕资料，和林知一起想。</h2></header><p class="entry-demo-label">对话演示 · 预先编写，不会向 AI 发送消息</p><blockquote class="entry-demo-source">引用：{{ example.question }}<p>{{ example.context }}</p></blockquote><div class="entry-demo-conversation"><img :src="artwork.mentor" alt="林知"><div><h3>林知</h3><p>{{ example.prompt }}</p></div></div><div class="entry-demo-prompts"><button class="entry-button secondary" @click="demoPrompt='hint'">先给我一点线索</button><button class="entry-button secondary" @click="demoPrompt='reason'">换一种讲法</button></div><div v-if="demoPrompt" class="entry-demo-answer" role="status"><strong>示例讲解</strong><p>{{ demoPrompt==='hint'?example.hint:example.reason }}</p></div><p>想继续真实讨论，可以把这个示例带入自己的学习目标。</p><button class="entry-button" @click="emit('start-course',example)">用这个示例开始学习</button></TabsContent>
      <TabsContent value="practice" class="entry-tab-body"><header><h2>换一个例子，检查理解。</h2></header><p>{{ example.practice }}</p><fieldset class="entry-practice-options"><legend>你的选择（仅当前示例）</legend><label v-for="option in example.practiceOptions" :key="option" :class="{selected:practiceChoice===option}"><input v-model="practiceChoice" type="radio" :name="'practice-'+example.id" :value="option">{{ option }}</label></fieldset><div v-if="practiceChoice" class="entry-demo-answer" role="status"><h3>{{ practiceChoice===example.practiceAnswer?'这次的推理方向是对的':'再检查一下过程' }}</h3><p>{{ practiceChoice===example.practiceAnswer?example.practiceReason:example.hint }}</p><button class="entry-text-link" @click="activeTab='read';explanation=true">回看讲解思路</button></div><p>这里的选择不会记录到你的学习表现。进入学习空间后，正式作答会保留证据。</p><button class="entry-button" @click="emit('start-course',example)">用这个示例开始学习</button></TabsContent>
    </TabsRoot>
  </div>
  <section class="entry-example-next"><a :href="'/examples?course='+nextExample.id" @click.prevent="select(nextExample.id)">下一个示例：{{ nextExample.title }}<img :src="icon('arrow-right')" alt=""></a><button class="entry-button secondary" @click="emit('new-goal')">从自己的目标开始</button></section>
</main>
</template>
